MATCH (anchorClass:类 {
  全限定名: 'auth.service.impl.TokenServiceImpl'
})-[:接口实现]->(interfaceClass:类)
RETURN DISTINCT interfaceClass.全限定名 AS 接口全限定名
ORDER BY 接口全限定名

MATCH (senderService:微服务 {
  服务名称: 'ts-preserve-service'
})-[dependency:消息依赖]->(receiverService:微服务 {
  服务名称: 'ts-notification-service'
})
RETURN DISTINCT
  dependency.交换机名称 AS 交换机名称,
  dependency.队列名称 AS 队列名称,
  dependency.路由键 AS 路由键
ORDER BY 交换机名称, 队列名称, 路由键
